window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _rm = SLP.books.find(function(b){ return b.id === "rom"; });
if (!_rm) throw new Error("data/canon.js must load before nt-05-rom-1cor.js");
(_rm.chapters = _rm.chapters || []).push(
  { n:1, summary:"Paul opens his letter with a formal greeting: set apart to preach the gospel promised by the prophets concerning God's Son, who was made of the seed of David and declared to be the Son of God with power by the resurrection from the dead. He thanks God for the Roman saints, whose faith is famous throughout the world, and explains that he has often planned to visit them but has been hindered, being a debtor to Greeks and barbarians alike and ready to preach at Rome. His thesis: he is not ashamed of the gospel of Christ, for it is the power of God unto salvation to every one that believeth, revealing the righteousness of God from faith to faith — the just shall live by faith. Then he shows why all need that righteousness: God's eternal power and Godhead are clearly seen in creation, yet humanity did not glorify or thank Him, exchanged His glory for images, and was given up to uncleanness, vile affections, and a reprobate mind.",
    context:"Paul writes to the saints at Rome, a congregation he had not yet visited, traditionally from Corinth near the end of his third missionary journey around A.D. 57-58.",
    keyVerses:[
      { ref:"Romans 1:16", text:"For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek." },
      { ref:"Romans 1:17", text:"For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith." },
      { ref:"Romans 1:20", text:"For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:" }
    ],
    takeaway:"The gospel is God's power to save everyone who believes, and it makes the righteous life possible.",
    quiz:[
      { q:"How was Jesus Christ declared to be the Son of God with power, according to Romans 1?", choices:["By the resurrection from the dead","By walking on the Sea of Galilee","By an angelic choir at Bethlehem","By his miracles at Cana"], a:0, why:"Verses 3-4 say he was made of the seed of David according to the flesh, and declared to be the Son of God with power by the resurrection from the dead." },
      { q:"What does Paul say the gospel reveals?", choices:["A new calendar of feasts","The righteousness of God, from faith to faith","The hidden history of Rome","The lineage of Israel's kings"], a:1, why:"Verse 17 says therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith." },
      { q:"Why are people without excuse before God, according to this chapter?", choices:["Because God never spoke to them","Because judgment day is unpredictable","Because His eternal power and Godhead are clearly seen in the things that are made","Because conscience alone condemns them"], a:2, why:"Verse 20 says the invisible things of him, including his eternal power and Godhead, are clearly seen from the creation of the world, so that they are without excuse." }
    ] },
  { n:2, summary:"Paul turns from the pagan world to anyone who judges, arguing that condemning others while doing the same things brings God's righteous judgment on yourself, because despising His goodness instead of letting it lead you to repentance only treasures up wrath. God renders to every person according to his deeds, without respect of persons: those who sin without the law perish without it, and those who sin under the law are judged by it, for it is the doers of the law who are justified, not the hearers; even Gentiles who do by nature what the law requires show its work written in their hearts. Finally Paul confronts the boastful Jew: teaching the law while breaking it dishonors God, and outward circumcision profits nothing without obedience. The true Jew is one inwardly, whose circumcision is that of the heart, in the spirit, whose praise is of God and not of men.",
    context:"Paul continues his case by turning from the pagan world to the moralizer and the Jew, showing that judging others while doing the same things brings condemnation.",
    keyVerses:[
      { ref:"Romans 2:4", text:"Or despisest thou the riches of his goodness and forbearance and longsuffering; not knowing that the goodness of God leadeth thee to repentance?" },
      { ref:"Romans 2:11", text:"For there is no respect of persons with God." },
      { ref:"Romans 2:29", text:"But he is a Jew, which is one inwardly; and circumcision is that of the heart, in the spirit, and not in the letter; whose praise is not of men, but of God." }
    ],
    takeaway:"God judges by what we actually do, not what we claim to know; His goodness is meant to lead us to repentance.",
    quiz:[
      { q:"What does Paul say is written in the hearts of Gentiles who do the things contained in the law?", choices:["The names of the twelve tribes","The work of the law","A covenant of circumcision","The history of Rome"], a:1, why:"Verses 14-15 say the Gentiles, having not the law, show the work of the law written in their hearts, their conscience bearing witness." },
      { q:"Who does Paul say is a Jew before God?", choices:["Anyone descended from Abraham","Whoever memorizes the law","One who is one inwardly, with circumcision of the heart in the spirit","Only a person born in Judea"], a:2, why:"Verses 28-29 teach that he is not a Jew who is one outwardly; the praise of the true Jew is of God, not of men." },
      { q:"What does the chapter say happens to those who despise God's goodness instead of repenting?", choices:["They gain extra time to change","God overlooks their sins","Their judgment transfers to their ancestors","They treasure up wrath against the day of righteous judgment"], a:3, why:"Verse 5 says that after thy hardness and impenitent heart thou treasurest up unto thyself wrath against the day of wrath." }
    ] },
  { n:3, summary:"Paul asks whether judgment cancels Israel's advantages: they have much advantage, chiefly because unto them were committed the oracles of God, yet unbelief cannot make God's faithfulness void. If our unrighteousness highlights God's righteousness, is God unrighteous to take vengeance? God forbid, or He could not judge the world; and the slanderous claim that Paul taught do evil that good may come is justly condemned. Scripture concludes that Jews and Gentiles are all under sin: none righteous, none seeking God, every mouth stopped, the whole world guilty before God. By the deeds of the law no flesh is justified, for by the law is the knowledge of sin; but the righteousness of God without the law is now revealed, and all who believe are justified freely by His grace through the redemption that is in Christ Jesus, whom God set forth as a propitiation through faith in His blood. Boasting is excluded by the law of faith, and faith does not void the law — it establishes it.",
    context:"Paul answers the objection that his teaching cancels Israel's privileges, showing instead that Jew and Gentile alike stand guilty before God and need grace.",
    keyVerses:[
      { ref:"Romans 3:23", text:"For all have sinned, and come short of the glory of God;" },
      { ref:"Romans 3:24", text:"Being justified freely by his grace through the redemption that is in Christ Jesus:" },
      { ref:"Romans 3:28", text:"Therefore we conclude that a man is justified by faith without the deeds of the law." }
    ],
    takeaway:"Everyone falls short of God's glory, and everyone is offered justification freely by His grace through Jesus Christ.",
    quiz:[
      { q:"According to Romans 3:2, what chief advantage did the Jews receive?", choices:["A standing army","Temple wealth","That unto them were committed the oracles of God","Freedom from judgment"], a:2, why:"Paul answers that the Jew's advantage is much every way, chiefly because unto them were committed the oracles of God." },
      { q:"Since no flesh is justified by the deeds of the law, what does Paul say the law provides?", choices:["Eternal security","The knowledge of sin","A record of ancestry","A civil court system"], a:3, why:"Verse 20 says by the deeds of the law there shall no flesh be justified, for by the law is the knowledge of sin." },
      { q:"Who needs the redemption that is in Christ Jesus, according to this chapter?", choices:["All have sinned and come short of the glory of God","Only uncircumcised Gentiles","Only the violently wicked","Only those without scripture"], a:0, why:"Verses 22-24 declare the righteousness of God by faith of Jesus Christ unto all and upon all them that believe, for all have sinned." }
    ] },
  { n:4, summary:"Paul calls Abraham as the decisive witness: if he was justified by works he could boast, but scripture says he believed God, and it was counted unto him for righteousness. A worker earns wages as a debt, but the believer's faith is counted for righteousness, and David sings of the blessedness of those whose sins are forgiven and covered. Abraham was counted righteous while still uncircumcised, so circumcision was only a seal, making him the father of all who believe; the promise that he should be heir of the world came not through the law but through the righteousness of faith, so the promise might be sure to all the seed. Against hope, at about a hundred years old, he staggered not at the promise of God through unbelief but was fully persuaded that God was able to perform it. This was written for us also, who believe on Him that raised up Jesus our Lord, delivered for our offences and raised again for our justification.",
    context:"Paul turns to Abraham to prove from Israel's own scriptures that righteousness is counted by faith, before and apart from the works of the law.",
    keyVerses:[
      { ref:"Romans 4:3", text:"For what saith the scripture? Abraham believed God, and it was counted unto him for righteousness." },
      { ref:"Romans 4:20", text:"He staggered not at the promise of God through unbelief; but was strong in faith, giving glory to God;" },
      { ref:"Romans 4:25", text:"Who was delivered for our offences, and was raised again for our justification." }
    ],
    takeaway:"Faith, not performance, is what God counts for righteousness — trust His promises even when they look impossible.",
    quiz:[
      { q:"How old was Abraham, roughly, when he staggered not at the promise of God?", choices:["About forty years old","About sixty years old","About eighty years old","About a hundred years old"], a:3, why:"Verse 19 says he considered not his own body now dead, when he was about an hundred years old, neither the deadness of Sara's womb." },
      { q:"Why does Paul emphasize that Abraham's righteousness was counted before circumcision?", choices:["So Abraham could be the father of all them that believe, circumcised or not","To show circumcision is painful","To argue that Abraham despised the covenant","Because Abraham forgot the ritual"], a:0, why:"Verse 11 says he received circumcision as a seal of the righteousness of the faith he had yet being uncircumcised, that he might be the father of all them that believe." },
      { q:"What does Abraham's example teach about believing God's promises?", choices:["Hope requires seeing results first","Against hope he believed in hope, fully persuaded that what God had promised He was able to perform","Faith must wait for perfect circumstances","Promises apply only to the young"], a:1, why:"Verses 18-21 say he against hope believed in hope and was fully persuaded that what God had promised He was able also to perform." }
    ] },
  { n:5, summary:"Being justified by faith, Paul says, we have peace with God and access into grace, so we rejoice in hope of the glory of God — and even in tribulations, which work patience, then experience, then hope, because the love of God is shed abroad in our hearts by the Holy Ghost. The proof of that love is timing: while we were yet without strength, and still sinners, Christ died for us, the ungodly. Justified by His blood, we are saved from wrath, reconciled to God by the death of His Son, and saved by His life. Paul then sets Adam against Christ: by one man sin entered the world, and death passed upon all men; yet the free gift is not like the offence, for where sin abounded, grace did much more abound. As by one man's disobedience many were made sinners, so by the obedience of one shall many be made righteous, and grace reigns unto eternal life by Jesus Christ our Lord.",
    context:"Paul moves from justification to its fruits, setting Adam, through whom sin and death entered, against Christ, through whom grace reigns.",
    keyVerses:[
      { ref:"Romans 5:1", text:"Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:" },
      { ref:"Romans 5:8", text:"But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us." },
      { ref:"Romans 5:19", text:"For as by one man's disobedience many were made sinners, so by the obedience of one shall many be made righteous." }
    ],
    takeaway:"Because Christ died for us while we were yet sinners, grace can reign where sin once ruled.",
    quiz:[
      { q:"What chain does Paul say tribulation works in Romans 5?", choices:["Patience, experience, and hope","Fear, doubt, and despair","Strength, wealth, and honor","Wisdom, silence, and rest"], a:0, why:"Verses 3-4 say tribulation worketh patience; and patience, experience; and experience, hope." },
      { q:"Why can believers rejoice in hope of the glory of God, even in tribulation?", choices:["Because trials are imaginary","Because the love of God is shed abroad in our hearts by the Holy Ghost","Because suffering erases past sins","Because hope depends on comfortable living"], a:1, why:"Verse 5 says hope maketh not ashamed, because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us." },
      { q:"What does the Adam-and-Christ comparison reveal about the reach of grace?", choices:["Adam's fall touched only himself","Grace merely balances Adam's sin","By one man's disobedience many were made sinners; by the obedience of one, many are made righteous","Only people born after Christ can be saved"], a:2, why:"Verses 18-19 contrast the offence of one, bringing condemnation, with the righteousness of one, bringing the free gift unto justification of life." }
    ] },
  { n:6, summary:"If grace abounds where sin abounds, should we keep sinning so grace grows? God forbid, Paul answers: we who are dead to sin cannot keep living in it. His ground is baptism — as many as were baptized into Jesus Christ were baptized into His death, buried with Him so that, like Christ raised from the dead by the glory of the Father, we should walk in newness of life. Our old man is crucified with Him so the body of sin might be destroyed, and we should not serve sin any longer. Therefore reckon yourselves dead indeed unto sin but alive unto God: refuse to let sin reign in your mortal body, and yield your members as instruments of righteousness, for you are not under the law but under grace. Yet grace does not license sin, for whoever you yield yourselves to obey, his servants you are; freed from sin, you became servants of righteousness, with fruit unto holiness and the end everlasting life.",
    context:"Paul answers the charge that grace encourages sinning, arguing from baptism that believers have died to sin and risen to walk in newness of life.",
    keyVerses:[
      { ref:"Romans 6:1", text:"What shall we say then? Shall we continue in sin, that grace may abound?" },
      { ref:"Romans 6:4", text:"Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life." },
      { ref:"Romans 6:23", text:"For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord." }
    ],
    takeaway:"Baptism joins us to Christ's death and resurrection so we can stop serving sin and start serving righteousness.",
    quiz:[
      { q:"Into whose death does Paul say believers were baptized?", choices:["Moses","Jesus Christ","John the Baptist","The prophets"], a:1, why:"Verse 3 says so many of us as were baptized into Jesus Christ were baptized into his death." },
      { q:"What image does Paul use to show that grace does not license sin?", choices:["A race with a prize","A farmer planting seed","A servant obeying whichever master he yields to","A courtroom weighing evidence"], a:2, why:"Verses 16-18 ask to whom ye yield yourselves servants to obey, whether of sin unto death or of obedience unto righteousness." },
      { q:"What two ends does Romans 6:23 set before every person?", choices:["Comfort now and comfort later","Death as the wages of sin, or eternal life as the gift of God","Poverty or prosperity","Knowledge or ignorance"], a:3, why:"Verse 23 says the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord." }
    ] },
  { n:7, summary:"Paul begins with marriage law: a wife is bound to her husband while he lives, but his death frees her. So believers, made dead to the law by the body of Christ, are married to another — Him who is raised from the dead — to bring forth fruit unto God, serving in newness of spirit, not in the oldness of the letter. Paul then guards the law from blame: the law is not sin; it is how he came to know lust, for the commandment said, Thou shalt not covet. Sin seized the commandment as its occasion, so the commandment ordained to life proved unto death, while the law itself remains holy, and just, and good. The trouble is the flesh: I am carnal, sold under sin — doing the evil I hate, not the good I would, with a law in my members warring against the law of my mind. The cry, O wretched man that I am, finds its answer: I thank God through Jesus Christ our Lord.",
    context:"Paul defends the law itself while describing the inward war of a person who wants to do good but finds sin dwelling in his flesh.",
    keyVerses:[
      { ref:"Romans 7:12", text:"Wherefore the law is holy, and the commandment holy, and just, and good." },
      { ref:"Romans 7:24", text:"O wretched man that I am! who shall deliver me from the body of this death?" },
      { ref:"Romans 7:25", text:"I thank God through Jesus Christ our Lord. So then with the mind I myself serve the law of God; but with the flesh the law of sin." }
    ],
    takeaway:"The law diagnoses sin but cannot cure it; deliverance comes only through Jesus Christ our Lord.",
    quiz:[
      { q:"Which commandment does Paul quote as the one that revealed lust to him?", choices:["Thou shalt not steal","Thou shalt not kill","Thou shalt not covet","Honor thy father and thy mother"], a:2, why:"Verse 7 says I had not known lust, except the law had said, Thou shalt not covet." },
      { q:"How does Paul describe the inward conflict of the willing but struggling person?", choices:["A battle already won by willpower","Peace between equal desires","A reason to stop obeying","Another law in his members warring against the law of his mind"], a:3, why:"Verse 23 says he sees another law in his members warring against the law of his mind and bringing him into captivity." },
      { q:"What answer does Paul give to the cry, Who shall deliver me from the body of this death?", choices:["I thank God through Jesus Christ our Lord","Stricter rule-keeping by effort","Ignoring the flesh altogether","Moving to a quieter city"], a:0, why:"Verse 25 answers the cry of verse 24 with thanksgiving through Jesus Christ our Lord." }
    ] },
  { n:8, summary:"Paul announces the great turn: there is now no condemnation to those in Christ Jesus who walk after the Spirit, for what the law could not do, God did by sending His own Son, condemning sin in the flesh. To be carnally minded is death, for the carnal mind is enmity against God; to be spiritually minded is life and peace. Believers are not debtors to the flesh: through the Spirit they mortify the deeds of the body and live. As many as are led by the Spirit of God are the sons of God, crying Abba, Father, the Spirit witnessing with our spirit that we are God's children — heirs of God and joint-heirs with Christ, if we suffer with Him. Creation itself groans for that manifestation; the Spirit helps our infirmities in prayer; and all things work together for good to them that love God. Nothing in death or life, present or future, can separate us from the love of God in Christ Jesus our Lord.",
    context:"Paul lifts the believer from the losing struggle of the flesh to the Spirit's power, adoption as children of God, and a love that cannot be broken.",
    keyVerses:[
      { ref:"Romans 8:1", text:"There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit." },
      { ref:"Romans 8:16", text:"The Spirit itself beareth witness with our spirit, that we are the children of God:" },
      { ref:"Romans 8:28", text:"And we know that all things work together for good to them that love God, to them who are the called according to his purpose." }
    ],
    takeaway:"Nothing in this world or beyond it can separate God's children from His love in Christ Jesus.",
    quiz:[
      { q:"What do believers cry by the Spirit of adoption, according to Romans 8:15?", choices:["Hosanna","Maran-atha","Alleluia","Abba, Father"], a:3, why:"Verse 15 says ye have received the Spirit of adoption, whereby we cry, Abba, Father." },
      { q:"Why can the carnal mind never please God?", choices:["It is enmity against God and is not subject to the law of God","It lacks education","It is too occupied with work","It trusts the wrong teachers"], a:0, why:"Verses 7-8 say the carnal mind is enmity against God, is not subject to the law of God, and they that are in the flesh cannot please God." },
      { q:"How does this chapter measure present suffering against future glory?", choices:["Suffering outweighs glory","The sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us","Glory erases the need for endurance","Suffering proves God's absence"], a:1, why:"Verse 18 says the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us." }
    ] },
  { n:9, summary:"Paul opens his heart: he has great heaviness and continual sorrow for his kinsmen, the Israelites, to whom pertain the adoption, the glory, the covenants, the giving of the law, and the promises, and of whom Christ came after the flesh. Yet the word of God has not failed, for they are not all Israel which are of Israel: the children of the promise are counted for the seed. Before Jacob and Esau had done good or evil, the elder was set to serve the younger, so that God's purpose according to election might stand, not of works but of Him that calleth. Is God unrighteous? He shows mercy on whom He will have mercy: it is not of him that willeth nor of him that runneth, but of God that sheweth mercy, and Paul answers the objector with the potter and the clay. Then the prophets: Gentiles who sought righteousness by faith attained it, while Israel, pursuing it by the works of the law, stumbled at that stumblingstone.",
    context:"Paul grieves over unbelieving Israel and explains that God's promises run through promise and election and mercy, not mere descent or works.",
    keyVerses:[
      { ref:"Romans 9:6", text:"Not as though the word of God hath taken none effect. For they are not all Israel, which are of Israel:" },
      { ref:"Romans 9:16", text:"So then it is not of him that willeth, nor of him that runneth, but of God that sheweth mercy." },
      { ref:"Romans 9:21", text:"Hath not the potter power over the clay, of the same lump to make one vessel unto honour, and another unto dishonour?" }
    ],
    takeaway:"God's promises stand on His calling and mercy, received by faith, not on pedigree or the works of the law.",
    quiz:[
      { q:"From which tribe does Paul say he descends, proving God has not cast away Israel?", choices:["Benjamin","Judah","Levi","Dan"], a:0, why:"Verse 1 says Hath God cast away his people? God forbid, for Paul is an Israelite of the seed of Abraham, of the tribe of Benjamin." },
      { q:"What point does the potter and the clay make about objecting to God's ways?", choices:["People have no real choices","The thing formed should not argue with him that formed it","God acts without purpose","Only priests may ask questions"], a:1, why:"Verse 20 asks shall the thing formed say to him that formed it, Why hast thou made me thus?" },
      { q:"Why did Israel miss the righteousness it pursued while Gentiles attained it?", choices:["The Gentiles worked harder","Israel lacked the scriptures","Israel sought it by the works of the law instead of by faith","God canceled the covenants"], a:2, why:"Verse 32 says they sought it not by faith, but as it were by the works of the law; for they stumbled at that stumblingstone." }
    ] },
  { n:10, summary:"Paul's heart's desire and prayer to God for Israel is that they might be saved: they have a zeal of God, but not according to knowledge, ignorant of God's righteousness and going about to establish their own. Christ is the end of the law for righteousness to every one that believeth. The righteousness of the law says do and live, but the righteousness of faith puts the word near — in the mouth and in the heart: confess with thy mouth the Lord Jesus, believe in thine heart that God hath raised him from the dead, and thou shalt be saved. There is no difference between the Jew and the Greek, for whosoever shall call upon the name of the Lord shall be saved. But no one can call on one they have not believed, or believe in one they have not heard, so preachers must be sent: faith cometh by hearing, and hearing by the word of God. Israel heard, yet stood as a disobedient and gainsaying people.",
    context:"Paul explains why zealous Israel missed salvation by seeking their own righteousness instead of submitting to God's righteousness by faith in Christ.",
    keyVerses:[
      { ref:"Romans 10:4", text:"For Christ is the end of the law for righteousness to every one that believeth." },
      { ref:"Romans 10:9", text:"That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved." },
      { ref:"Romans 10:17", text:"So then faith cometh by hearing, and hearing by the word of God." }
    ],
    takeaway:"Salvation is near — confess the Lord Jesus and believe God raised Him; faith comes by hearing the word of God.",
    quiz:[
      { q:"What did Paul say Israel had, but not according to knowledge?", choices:["Wealth","A zeal of God","Temple choirs","Scribes and scholars"], a:1, why:"Verse 2 says I bear them record that they have a zeal of God, but not according to knowledge." },
      { q:"What chain does Paul trace from calling on the Lord back to preaching?", choices:["Fasting leads to prayer, prayer to revelation","The law leads to sin, sin to death","Calling needs believing; believing needs hearing; hearing needs a preacher; preaching needs one sent","Baptism leads to membership and then salvation"], a:2, why:"Verses 14-15 ask how they shall call on him in whom they have not believed, and how shall they hear without a preacher, and how shall they preach except they be sent." },
      { q:"How is salvation received according to Romans 10:9?", choices:["By keeping silence about faith","By finding truth through personal ascent","By confessing the Lord Jesus and believing God raised him from the dead","By lineage and birthright alone"], a:3, why:"Verse 9 says if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved." }
    ] },
  { n:11, summary:"Hath God cast away his people? God forbid, Paul answers, counting himself an Israelite of the tribe of Benjamin. As in Elijah's day, when God reserved seven thousand who had not bowed to Baal, there is now a remnant according to the election of grace — and if by grace, it is no more of works. Israel has not obtained what it sought, but the election has; their stumble is not a final fall: through their fall salvation is come unto the Gentiles, and their receiving again will be life from the dead. Paul pictures an olive tree: natural branches broken off for unbelief, wild branches grafted in, standing only by faith — and God is able to graft the natural branches in again. A mystery remains: blindness in part has happened to Israel until the fulness of the Gentiles come in, and so all Israel shall be saved, for God has concluded all in unbelief that He might have mercy upon all — His gifts and calling are without repentance.",
    context:"Paul works out Israel's place in God's plan, using an olive tree to warn Gentile believers against pride while promising Israel's future ingathering.",
    keyVerses:[
      { ref:"Romans 11:5", text:"Even so then at this present time also there is a remnant according to the election of grace." },
      { ref:"Romans 11:26", text:"And so all Israel shall be saved: as it is written, There shall come out of Sion the Deliverer, and shall turn away ungodliness from Jacob:" },
      { ref:"Romans 11:29", text:"For the gifts and calling of God are without repentance." }
    ],
    takeaway:"God's covenant mercy never fails: the remnant stands by grace, and His gifts and calling are without repentance.",
    quiz:[
      { q:"In Elijah's time, how many men had God reserved who had not bowed the knee to Baal?", choices:["Three thousand","Five hundred","Seven thousand","Twelve thousand"], a:2, why:"Verse 4 says I have reserved to myself seven thousand men, who have not bowed the knee to the image of Baal." },
      { q:"In the olive tree picture, why were branches broken off, and how do grafted branches stand?", choices:["Broken off by persecution; kept by wealth","Broken off by unbelief; grafted branches stand by faith","Broken off by poverty; kept by works","Broken off by exile; kept by lineage"], a:3, why:"Verse 20 says because of unbelief they were broken off, and thou standest by faith; be not highminded, but fear." },
      { q:"What warning does Paul give Gentile believers about their place in the olive tree?", choices:["Boast not against the branches, and take heed lest God also spare not thee","Their place can never be lost","Israel has no future in the tree","Pride is safe once grafted in"], a:0, why:"Verses 18 and 21 warn against boasting against the branches, for if God spared not the natural branches, take heed lest he also spare not thee." }
    ] },
  { n:12, summary:"Paul's practical section begins with an invitation: present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service. Instead of being conformed to this world, be transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God. Humility comes first — not to think of himself more highly than he ought — and from it grows Paul's picture of the Church: many members in one body, with gifts differing according to grace, whether prophecy, ministry, teaching, exhortation, giving, ruling, or showing mercy. Then a portrait of love without dissimulation: abhor evil and cleave to good; prefer one another in honor; be fervent in spirit, serving the Lord; rejoice in hope, be patient in tribulation, continue instant in prayer; distribute to the saints and practice hospitality; bless persecutors and weep with those who weep. Refuse revenge, for vengeance belongs to the Lord; feed your hungry enemy, and overcome evil with good.",
    context:"Paul turns from doctrine to discipleship, describing how the transformed believer lives: humility, service, love, and forgiveness in the Church.",
    keyVerses:[
      { ref:"Romans 12:1", text:"I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service." },
      { ref:"Romans 12:2", text:"And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God." },
      { ref:"Romans 12:21", text:"Be not overcome of evil, but overcome evil with good." }
    ],
    takeaway:"True worship is offering yourself as a living sacrifice, renewed in mind, overcoming evil with good.",
    quiz:[
      { q:"What does Paul beseech the brethren to present to God in Romans 12:1?", choices:["Burnt offerings of animals","Gold for the treasury","Firstfruits of the harvest","Their bodies, a living sacrifice"], a:3, why:"Verse 1 asks that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service." },
      { q:"How are believers kept from being conformed to this world?", choices:["By being transformed by the renewing of the mind","By avoiding all nonbelievers","By memorizing civil law","By keeping silent in meetings"], a:0, why:"Verse 2 says be not conformed to this world: but be ye transformed by the renewing of your mind." },
      { q:"How does Paul say to treat a persecuting enemy?", choices:["Repay him in kind","Bless him, feed him if he hungers, and leave vengeance to the Lord","Avoid him until he apologizes","Report him to the magistrates only"], a:1, why:"Verses 14 and 19-20 say bless them which persecute you, avenge not yourselves, and if thine enemy hunger, feed him." }
    ] },
  { n:13, summary:"Paul turns to civic life: let every soul be subject unto the higher powers, for there is no power but of God, and the powers that be are ordained of God. Rulers are not a terror to good works but to the evil, bearing the sword as God's minister; so subjection is owed not only for wrath but also for conscience sake, along with tribute, custom, and honor to whom they are due. The one debt that remains is love, for he that loveth another hath fulfilled the law: adultery, killing, stealing, false witness, and coveting are all briefly comprehended in loving thy neighbour as thyself, for love worketh no ill to his neighbour. Finally Paul sounds the alarm: now it is high time to awake out of sleep, for salvation is nearer than when we believed. Cast off the works of darkness, put on the armour of light, and put ye on the Lord Jesus Christ, making no provision for the flesh.",
    context:"Paul teaches civic duty and love's fulfillment of the law, then urges the saints to wake from sleep and cast off the works of darkness.",
    keyVerses:[
      { ref:"Romans 13:1", text:"Let every soul be subject unto the higher powers. For there is no power but of God: the powers that be are ordained of God." },
      { ref:"Romans 13:8", text:"Owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law." },
      { ref:"Romans 13:11", text:"And that, knowing the time, that now it is high time to awake out of sleep: for now is our salvation nearer than when we believed." }
    ],
    takeaway:"Love your neighbor and owe no debt but love, walking honestly as children of the day.",
    quiz:[
      { q:"How many commandments does Paul name before summing them up in loving thy neighbour as thyself?", choices:["Five","Four","Three","Six"], a:0, why:"Verse 9 names adultery, killing, stealing, false witness, and coveting, then says any other commandment is briefly comprehended in loving thy neighbour as thyself." },
      { q:"Why does Paul say subjection to authorities is owed beyond fear of punishment?", choices:["Not only for wrath, but also for conscience sake","To earn Roman citizenship","To gain tax advantages","To spread the gospel by decree"], a:1, why:"Verse 5 says wherefore ye must needs be subject, not only for wrath, but also for conscience sake." },
      { q:"What does Paul call the one debt that is never finished being paid?", choices:["Tribute to the government","Honor to elders","The continuing debt to love one another","Custom owed at the gate"], a:2, why:"Verse 8 says owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law." }
    ] },
  { n:14, summary:"Two scruples divide the congregation: one believeth that he may eat all things, while another who is weak eateth herbs; one esteemeth one day above another, another esteemeth every day alike. Paul's rule is to receive the weak in faith without arguing over doubtful points, for God hath received him and each stands or falls to his own master. Whatever we do, we do to the Lord: none of us liveth to himself, and whether we live or die, we are the Lord's. Since every one of us shall give account of himself to God, stop judging your brother and judge this instead — put no stumblingblock in his way. Nothing is unclean of itself, but destroying a brother with your meat is not walking charitably, for the kingdom of God is not meat and drink but righteousness, and peace, and joy in the Holy Ghost. Follow after peace and edification, for whatsoever is not of faith is sin.",
    context:"Paul addresses quarrels over food and holy days in the Roman congregation, teaching tolerance toward the weak in faith and judgment-free charity.",
    keyVerses:[
      { ref:"Romans 14:12", text:"So then every one of us shall give account of himself to God." },
      { ref:"Romans 14:17", text:"For the kingdom of God is not meat and drink; but righteousness, and peace, and joy in the Holy Ghost." },
      { ref:"Romans 14:19", text:"Let us therefore follow after the things which make for peace, and things wherewith one may edify another." }
    ],
    takeaway:"The kingdom of God is not meat and drink but righteousness, peace, and joy — so make peace, not judgments.",
    quiz:[
      { q:"What does the person weak in the faith eat, in Paul's example?", choices:["Only meat","Only herbs","Nothing but bread","Only food from the shambles"], a:1, why:"Verse 2 says one believeth that he may eat all things: another, who is weak, eateth herbs." },
      { q:"Why should the strong not use their freedom in a way that grieves a weaker brother?", choices:["Meat is forbidden for everyone","Roman law required restraint","Destroy not him with thy meat, for whom Christ died","Weaker members should leave the church"], a:2, why:"Verse 15 says if thy brother be grieved with thy meat, now walkest thou not charitably: destroy not him with thy meat, for whom Christ died." },
      { q:"What standard replaces judging a brother over food or days?", choices:["The strictest common practice","Every one of us shall give account of himself to God","Majority vote in the congregation","Silence about all differences"], a:3, why:"Verses 10-12 say we shall all stand before the judgment seat of Christ, and every one of us shall give account of himself to God." }
    ] },
  { n:15, summary:"Paul's closing appeal: we that are strong ought to bear the infirmities of the weak, and not to please ourselves, pleasing our neighbour for his good to edification, as Christ also pleased not himself. The scriptures written aforetime were written for our learning, that through patience and comfort of the scriptures we might have hope; so Paul prays that God will grant the Romans to be likeminded, glorifying God with one mind and one mouth — receive ye one another, as Christ also received us. Christ's ministry confirmed the promises made unto the fathers so that the Gentiles might glorify God for His mercy, exactly as the prophets foretold. Paul defends his boldness as the minister of Jesus Christ to the Gentiles: from Jerusalem to Illyricum he has fully preached the gospel, building on no other man's foundation. His plans: a contribution from Macedonia and Achaia for the poor saints at Jerusalem, then Rome on the way to Spain, asking their prayers that he may be delivered from unbelievers in Judaea.",
    context:"Paul closes the letter's teaching by urging the strong to bear the weak and reporting his plans: a relief offering for Jerusalem, then Rome, then Spain.",
    keyVerses:[
      { ref:"Romans 15:1", text:"We then that are strong ought to bear the infirmities of the weak, and not to please ourselves." },
      { ref:"Romans 15:4", text:"For whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope." },
      { ref:"Romans 15:13", text:"Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost." }
    ],
    takeaway:"The strong bear the weak, the scriptures give hope, and the God of hope fills believers with joy and peace.",
    quiz:[
      { q:"Toward what region does Paul plan to travel after visiting Rome?", choices:["Egypt","Spain","Greece","Syria"], a:2, why:"Verses 24 and 28 say when he takes his journey into Spain he will come to them, passing by on his way." },
      { q:"Why were the saints of Macedonia and Achaia sending a contribution to Jerusalem?", choices:["To pay back temple taxes","To fund Paul's journeys","To ransom prisoners","For the poor saints there, since Gentiles shared their spiritual things"], a:3, why:"Verses 26-27 say it pleased them to make a certain contribution for the poor saints at Jerusalem, whose debtors they are for spiritual things." },
      { q:"Why do the earlier scriptures remain worth reading, according to Paul?", choices:["Scripture was written aforetime for our learning, that through patience and comfort we might have hope","They record Roman law","They replace the need for prophets","They apply only to ancient Israel"], a:0, why:"Verse 4 says whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope." }
    ] },
  { n:16, summary:"The letter's last chapter is a gallery of real people: Phebe, a servant of the church at Cenchrea and a succourer of many, is commended to the Romans; Priscilla and Aquila, who laid down their own necks for Paul's life, host a church in their house; and a long list of women and men who labored in the Lord are greeted by name. Paul then warns the congregation to mark those who cause divisions and offences contrary to the doctrine they have learned and to avoid them, for such serve their own belly and deceive the simple with good words and fair speeches. Be wise unto that which is good, and simple concerning evil, for the God of peace shall bruise Satan under your feet shortly. Tertius, the scribe, and Gaius the host send greetings, and the letter ends in a doxology: the mystery kept secret since the world began is now made manifest and known to all nations for the obedience of faith.",
    context:"Paul closes with personal greetings to many named believers, a warning against those who cause divisions, and a final doxology.",
    keyVerses:[
      { ref:"Romans 16:1", text:"I commend unto you Phebe our sister, which is a servant of the church which is at Cenchrea:" },
      { ref:"Romans 16:17", text:"Now I beseech you, brethren, mark them which cause divisions and offences contrary to the doctrine which ye have learned; and avoid them." },
      { ref:"Romans 16:20", text:"And the God of peace shall bruise Satan under your feet shortly." }
    ],
    takeaway:"Ordinary faithful people carry the Lord's work, and divisions contrary to learned doctrine must be marked and avoided.",
    quiz:[
      { q:"Whom does Paul commend as a servant of the church which is at Cenchrea?", choices:["Persis","Priscilla","Junia","Phebe"], a:3, why:"Verse 1 says I commend unto you Phebe our sister, which is a servant of the church which is at Cenchrea." },
      { q:"What does Paul ask the Romans to do with those who cause divisions and offences contrary to learned doctrine?", choices:["Mark them and avoid them","Appoint them to teaching","Invite them to explain themselves","Send them to another city"], a:0, why:"Verse 17 says mark them which cause divisions and offences contrary to the doctrine which ye have learned; and avoid them." },
      { q:"What balance does Paul want in the face of deceivers with fair speeches?", choices:["Suspicion toward every teacher","Wise unto that which is good, and simple concerning evil","Wise concerning evil, simple about good","Equal trust in all voices"], a:1, why:"Verse 19 says I would have you wise unto that which is good, and simple concerning evil." }
    ] }
);
var _co = SLP.books.find(function(b){ return b.id === "1-cor"; });
if (!_co) throw new Error("data/canon.js must load before nt-05-rom-1cor.js");
(_co.chapters = _co.chapters || []).push(
  { n:1, summary:"After greeting the sanctified saints at Corinth and thanking God that they come behind in no gift, Paul moves quickly to his first problem: contentions among them. Members cry, I am of Paul, of Apollos, of Cephas, of Christ — and Paul asks, Is Christ divided? Was Paul crucified for you? He is grateful he baptized so few of them, for Christ sent him to preach the gospel, not with wisdom of words, lest the cross be made of none effect. The preaching of the cross is foolishness to them that perish but the power of God to the saved: the world by wisdom knew not God, so God saves them that believe by the foolishness of preaching. The Jews require a sign and the Greeks seek wisdom, but Paul preaches Christ crucified — God's power and wisdom to those called — choosing the weak and foolish things of the world so that no flesh should glory in His presence; he that glorieth, let him glory in the Lord.",
    context:"Paul and Sosthenes write to the church of God at Corinth, answering reports from Chloe's household that contentions are splitting the members into factions.",
    keyVerses:[
      { ref:"1 Corinthians 1:10", text:"Now I beseech you, brethren, by the name of our Lord Jesus Christ, that ye all speak the same thing, and that there be no divisions among you; but that ye be perfectly joined together in the same mind and in the same judgment." },
      { ref:"1 Corinthians 1:18", text:"For the preaching of the cross is to them that perish foolishness; but unto us which are saved it is the power of God." },
      { ref:"1 Corinthians 1:27", text:"But God hath chosen the foolish things of the world to confound the wise; and God hath chosen the weak things of the world to confound the things which are mighty;" }
    ],
    takeaway:"Christ is not divided: unity in His gospel outweighs loyalty to any teacher, and God's wisdom outranks the world's.",
    quiz:[
      { q:"Through whose household did Paul learn of the contentions among the Corinthians?", choices:["Chloe's house","Stephanas' house","Gaius' house","Crispus' house"], a:0, why:"Verse 11 says it hath been declared unto me of you, my brethren, by them which are of the house of Chloe, that there are contentions among you." },
      { q:"Why did Paul refuse to preach with wisdom of words?", choices:["He had no formal training","Lest the cross of Christ should be made of none effect","The Corinthians banned public speaking","To shorten his sermons"], a:1, why:"Verse 17 says Christ sent me not to baptize, but to preach the gospel: not with wisdom of words, lest the cross of Christ should be made of none effect." },
      { q:"What does this chapter teach about pride in human leaders?", choices:["Famous teachers deserve titles","Every faction honors Christ in its own way","No flesh should glory in His presence; he that glorieth, let him glory in the Lord","Gifted speakers should settle disputes"], a:2, why:"Verses 29-31 say that no flesh should glory in his presence, and he that glorieth, let him glory in the Lord." }
    ] },
  { n:2, summary:"Paul reminds the Corinthians how he came to them: not with excellency of speech or of wisdom, determined to know nothing among them save Jesus Christ, and him crucified. He was with them in weakness, fear, and much trembling, preaching not with enticing words of man's wisdom but in demonstration of the Spirit and of power, so their faith should not stand in the wisdom of men but in the power of God. Yet he does speak wisdom among the mature: the hidden wisdom of God, ordained before the world, which none of the princes of this world knew — had they known it, they would not have crucified the Lord of glory. Eye hath not seen, nor ear heard, the things God hath prepared for them that love him, but God reveals them by His Spirit, for only the Spirit of God knows the things of God. The natural man cannot receive these things, because they are spiritually discerned; the spiritual man judges all things, and we have the mind of Christ.",
    context:"Paul recalls preaching in Corinth in weakness and trembling, not in rhetoric, and explains why the Spirit is needed to understand the things of God.",
    keyVerses:[
      { ref:"1 Corinthians 2:2", text:"For I determined not to know any thing among you, save Jesus Christ, and him crucified." },
      { ref:"1 Corinthians 2:9", text:"But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him." },
      { ref:"1 Corinthians 2:14", text:"But the natural man receiveth not the things of the Spirit of God: for they are foolishness unto him: neither can he know them, because they are spiritually discerned." }
    ],
    takeaway:"Faith rests on God's power, not human eloquence; the deep things of God are known only through His Spirit.",
    quiz:[
      { q:"What two things alone did Paul determine to know among the Corinthians?", choices:["Law and gospel","Jesus Christ, and him crucified","Signs and wisdom","Prophecy and tongues"], a:1, why:"Verse 2 says I determined not to know any thing among you, save Jesus Christ, and him crucified." },
      { q:"Why can the natural man not receive the things of the Spirit of God?", choices:["He refuses to read scripture","He is too busy with daily work","They are foolishness to him, because they are spiritually discerned","God has concealed the scriptures"], a:2, why:"Verse 14 says the natural man receiveth not the things of the Spirit of God: for they are foolishness unto him, neither can he know them." },
      { q:"Where should the Corinthians' faith be rooted, according to Paul?", choices:["In the eloquence of speakers","In careful philosophy","In signs and wonders alone","Not in the wisdom of men, but in the power of God"], a:3, why:"Verse 5 says that your faith should not stand in the wisdom of men, but in the power of God." }
    ] },
  { n:3, summary:"The factions prove the Corinthians are still carnal, babes in Christ: Paul fed them with milk, not with meat, because envying, strife, and divisions show them walking as men. Who is Paul, who is Apollos, but ministers by whom ye believed? I have planted, Apollos watered; but God gave the increase — neither is anything, and each shall receive reward according to his own labour. As a wise masterbuilder Paul laid the foundation — other foundation can no man lay, which is Jesus Christ — and every builder must take heed what he adds. The fire shall try every man's work: what abides earns a reward; what burns brings loss, though he himself shall be saved, yet so as by fire. Finally: ye are the temple of God, and if any defile it, him shall God destroy. Let no man glory in men, for all things are yours, and ye are Christ's; and Christ is God's.",
    context:"Paul traces the faction fights back to spiritual immaturity and warns that every person's work in God's building will be tried by fire.",
    keyVerses:[
      { ref:"1 Corinthians 3:6", text:"I have planted, Apollos watered; but God gave the increase." },
      { ref:"1 Corinthians 3:11", text:"For other foundation can no man lay than that is laid, which is Jesus Christ." },
      { ref:"1 Corinthians 3:16", text:"Know ye not that ye are the temple of God, and that the Spirit of God dwelleth in you?" }
    ],
    takeaway:"Build only on the foundation of Jesus Christ; God will test every person's work by fire.",
    quiz:[
      { q:"In Paul's field image, what had Apollos done?", choices:["Planted","Reaped","Watered","Pruned"], a:2, why:"Verse 6 says I have planted, Apollos watered; but God gave the increase." },
      { q:"In the building image, what do the gold, silver, and precious stones versus wood, hay, and stubble show?", choices:["Ranks of church members","Rival congregations in Corinth","Old and New Covenants","The quality of each person's work, which the fire shall try"], a:3, why:"Verses 12-13 say every man's work shall be made manifest, for the fire shall try every man's work of what sort it is." },
      { q:"What does this chapter teach about competing for credit in the Lord's work?", choices:["Neither he that planteth nor he that watereth is anything; God giveth the increase","Loyal followers decide the credit","The largest faction wins","Only apostles may lay foundations"], a:0, why:"Verses 6-7 say neither is he that planteth any thing, neither he that watereth; but God that giveth the increase." }
    ] },
  { n:4, summary:"Paul accounts the apostles as ministers of Christ and stewards of the mysteries of God, and it is required in stewards that a man be found faithful. Human judgment settles nothing, for he that judgeth me is the Lord: judge nothing before the time, until the Lord come and bring to light the hidden things of the heart. The point of the Paul-versus-Apollos figure is that no one be puffed up for one against another: what hast thou that thou didst not receive? With irony Paul contrasts them — now ye are rich, ye reign as kings — with the apostles, set forth last, appointed to death: hungry, thirsty, buffeted, laboring with their own hands. He writes not to shame but to warn them as beloved sons: though ye have ten thousand instructors, yet not many fathers — in Christ Jesus I have begotten you through the gospel. Timotheus will remind them of his ways, for the kingdom of God is not in word, but in power.",
    context:"Paul describes apostles as stewards of the mysteries of God, contrasts their sufferings with the Corinthians' pride, and warns he is coming to test power, not speech.",
    keyVerses:[
      { ref:"1 Corinthians 4:2", text:"Moreover it is required in stewards, that a man be found faithful." },
      { ref:"1 Corinthians 4:5", text:"Therefore judge nothing before the time, until the Lord come, who both will bring to light the hidden things of darkness, and will make manifest the counsels of the hearts: and then shall every man have praise of God." },
      { ref:"1 Corinthians 4:20", text:"For the kingdom of God is not in word, but in power." }
    ],
    takeaway:"Stewards must be found faithful; the Lord alone judges hearts, for His kingdom is not in word but in power.",
    quiz:[
      { q:"Whom does Paul say he has sent to bring the Corinthians into remembrance of his ways in Christ?", choices:["Barnabas","Apollos","Sosthenes","Timotheus"], a:3, why:"Verse 17 says for this cause have I sent unto you Timotheus, who is my beloved son, and faithful in the Lord." },
      { q:"Why does Paul say to judge nothing before the time?", choices:["The Lord alone will bring to light the hidden things of darkness and the counsels of the hearts at His coming","Judgment is never permitted in the church","The Corinthians cannot reason fairly","Roman courts must decide first"], a:0, why:"Verse 5 says judge nothing before the time, until the Lord come, who both will bring to light the hidden things of darkness." },
      { q:"What does this chapter teach about the standard for servants of God?", choices:["Popularity confirms a steward's success","It is required in stewards that a man be found faithful","Stewards measure themselves by their followers","Comfort shows God's approval"], a:1, why:"Verse 2 says moreover it is required in stewards, that a man be found faithful; the Lord, not men, is the judge." }
    ] },
  { n:5, summary:"A case is commonly reported: a man has his father's wife — immorality not so much as named among the Gentiles — and instead of mourning, the congregation is puffed up. Paul has judged already: with the power of the Lord Jesus they are to deliver such an one unto Satan for the destruction of the flesh, that the spirit may be saved in the day of the Lord. Their glorying is not good, for a little leaven leaveneth the whole lump: purge out the old leaven and keep the feast of sincerity and truth, for Christ our passover is sacrificed for us. He clarifies his earlier letter: not to avoid the sinful people of the world — then must ye needs go out of the world — but not to keep company with any brother who is a fornicator, covetous, an idolater, a railer, a drunkard, or an extortioner. God judges them that are without; the church judges them that are within: put away that wicked person.",
    context:"Paul confronts an incestuous member the congregation has tolerated, ordering his removal for the sake of his spirit and the purity of the church.",
    keyVerses:[
      { ref:"1 Corinthians 5:6", text:"Your glorying is not good. Know ye not that a little leaven leaveneth the whole lump?" },
      { ref:"1 Corinthians 5:7", text:"Purge out therefore the old leaven, that ye may be a new lump, as ye are unleavened. For even Christ our passover is sacrificed for us:" },
      { ref:"1 Corinthians 5:13", text:"But them that are without God judgeth. Therefore put away from among yourselves that wicked person." }
    ],
    takeaway:"Tolerated sin spreads like leaven; a congregation must act in love to correct and ultimately save the sinner.",
    quiz:[
      { q:"What sin was commonly reported among the Corinthians?", choices:["A man had his father's wife","Stealing from the collection","Denying Christ publicly","Selling sacrifices"], a:0, why:"Verse 1 says it is reported commonly that there is fornication among you... that one should have his father's wife." },
      { q:"What does the leaven image teach about tolerated sin?", choices:["Sin is private and harmless","A little leaven leaveneth the whole lump","Only leaders' sins spread","One sinner proves all are guilty"], a:1, why:"Verse 6 says your glorying is not good. Know ye not that a little leaven leaveneth the whole lump?" },
      { q:"Why did Paul direct the church to put the offender away rather than ignore him?", choices:["To punish him permanently","That the spirit may be saved in the day of the Lord Jesus","To satisfy the Gentile neighbors","To raise money for the saints"], a:2, why:"Verse 5 says to deliver such an one unto Satan for the destruction of the flesh, that the spirit may be saved in the day of the Lord Jesus." }
    ] },
  { n:6, summary:"Paul turns to lawsuits: dare any of you, having a matter against another, go to law before the unjust, and not before the saints? Do ye not know that the saints shall judge the world — even angels? Brother going to law with brother before unbelievers is utterly a fault: why do ye not rather take wrong and suffer yourselves to be defrauded? Then the deeper point: the unrighteous shall not inherit the kingdom of God — fornicators, idolaters, adulterers, thieves, covetous, drunkards, revilers, extortioners — and such were some of you, but ye are washed, sanctified, justified in the name of the Lord Jesus. Not everything helpful is wise: I will not be brought under the power of any, for the body is not for fornication, but for the Lord. Your bodies are the members of Christ and the temple of the Holy Ghost; flee fornication, for ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's.",
    context:"Paul shames the Corinthians for suing each other before unbelieving judges and grounds sexual purity in the body's holiness as a temple of the Holy Ghost.",
    keyVerses:[
      { ref:"1 Corinthians 6:12", text:"All things are lawful unto me, but all things are not expedient: all things are lawful for me, but I will not be brought under the power of any." },
      { ref:"1 Corinthians 6:19", text:"What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?" },
      { ref:"1 Corinthians 6:20", text:"For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God's." }
    ],
    takeaway:"Your body is a temple of the Holy Ghost, bought with a price — so glorify God in body and in spirit.",
    quiz:[
      { q:"What civil dispute does Paul rebuke the Corinthians for taking before unbelievers?", choices:["Boundary quarrels with neighbors","Brother going to law with brother","Tax appeals to Rome","Inheritance claims at the temple"], a:1, why:"Verse 6 says but brother goeth to law with brother, and that before the unbelievers." },
      { q:"Why is fleeing fornication singled out among sins?", choices:["It cannot be repented of","It breaks Roman law","Every sin a man doeth is without the body, but fornication sinneth against his own body","It harms only the other person"], a:2, why:"Verse 18 says flee fornication. Every sin that a man doeth is without the body; but he that committeth fornication sinneth against his own body." },
      { q:"How does Paul say believers should treat their bodies?", choices:["As temporary and unimportant","As instruments of appetite","As belonging to themselves alone","As the temple of the Holy Ghost, bought with a price, to glorify God"], a:3, why:"Verses 19-20 say your body is the temple of the Holy Ghost... ye are not your own... ye are bought with a price: therefore glorify God in your body." }
    ] },
  { n:7, summary:"Answering the Corinthians' letter, Paul counsels balance: to avoid fornication, let every man have his own wife and every woman her own husband. Every man hath his proper gift of God: if they cannot contain, let them marry, for it is better to marry than to burn. To the married comes the Lord's command not to depart; if an unbelieving spouse is willing to stay, the believer should not leave, for the unbelieving wife is sanctified by the husband and the children holy — but if the unbelieving depart, a brother or sister is not under bondage, for God hath called us to peace. As the Lord hath called every one, so let him walk: circumcision is nothing, and uncircumcision is nothing, but the keeping of the commandments of God. Because the time is short, marrying involves no sin, and the single life attends upon the Lord without distraction: he that giveth in marriage doeth well, but he that giveth her not doeth better.",
    context:"Paul answers written questions about marriage, celibacy, mixed marriages with unbelievers, and abiding in one's calling amid the present distress.",
    keyVerses:[
      { ref:"1 Corinthians 7:7", text:"For I would that all men were even as I myself. But every man hath his proper gift of God, one after this manner, and another after that." },
      { ref:"1 Corinthians 7:9", text:"But if they cannot contain, let them marry: for it is better to marry than to burn." },
      { ref:"1 Corinthians 7:17", text:"But as God hath distributed to every man, as the Lord hath called every one, so let him walk. And so ordain I in all churches." }
    ],
    takeaway:"Marriage and singleness are each God-given callings: honor your covenant, and abide with God where He has called you.",
    quiz:[
      { q:"According to Paul, why should every man have his own wife and every woman her own husband?", choices:["To honor Roman custom","To enlarge the congregation","To avoid fornication","To inherit property lawfully"], a:2, why:"Verse 2 says nevertheless, to avoid fornication, let every man have his own wife, and let every woman have her own husband." },
      { q:"What does Paul counsel a believer whose unbelieving spouse is willing to live with them?", choices:["Leave at once to preserve purity","Demand conversion immediately","Treat the marriage as void","The believer should not leave, for the unbelieving spouse is sanctified by the believer"], a:3, why:"Verses 12-14 say if any brother hath a wife that believeth not, and she be pleased to dwell with him, let him not put her away, for the unbelieving wife is sanctified by the husband." },
      { q:"What principle from this chapter guides every circumstance of life?", choices:["As the Lord hath called every one, so let him walk, abiding with God","Only the married please God","Change your station to find peace","Freedom and calling cannot coexist"], a:0, why:"Verses 17 and 24 say as the Lord hath called every one, so let him walk, and let every man, wherein he is called, therein abide with God." }
    ] },
  { n:8, summary:"The Corinthians' slogan is knowledge — and Paul agrees that an idol is nothing in the world, and that there is none other God but one: to us there is but one God, the Father, and one Lord Jesus Christ, by whom are all things. But knowledge puffeth up, charity edifieth, and not every man has this knowledge: some, with conscience of the idol, eat the meat as a thing offered to an idol, and their weak conscience is defiled. Meat itself commends us nothing to God; the real issue is the neighbor. Take heed lest this liberty of yours become a stumblingblock to them that are weak, for if a weak believer sees you eating in an idol's temple, his conscience may be emboldened, and through thy knowledge shall the weak brother perish, for whom Christ died. Wounding a weak conscience is sinning against Christ; so if meat make my brother to offend, I will eat no flesh while the world standeth.",
    context:"Paul takes up food offered to idols, agreeing that an idol is nothing but insisting that love for a weak conscience limits the strong.",
    keyVerses:[
      { ref:"1 Corinthians 8:1", text:"Now as touching things offered unto idols, we know that we all have knowledge. Knowledge puffeth up, but charity edifieth." },
      { ref:"1 Corinthians 8:9", text:"But take heed lest by any means this liberty of yours become a stumblingblock to them that are weak." },
      { ref:"1 Corinthians 8:13", text:"Wherefore, if meat make my brother to offend, I will eat no flesh while the world standeth, lest I make my brother to offend." }
    ],
    takeaway:"Knowledge may prove you right, but charity protects the weak: love limits liberty for a brother's sake.",
    quiz:[
      { q:"How many gods does Paul say there are to us, according to 1 Corinthians 8:6?", choices:["Many gods and many lords","Two rival gods","An unknown number","One God, the Father, and one Lord Jesus Christ"], a:3, why:"Verse 6 says to us there is but one God, the Father, of whom are all things... and one Lord Jesus Christ, by whom are all things." },
      { q:"Why would Paul give up eating meat altogether?", choices:["Because wounding a weak brother's conscience is sinning against Christ","Because meat was expensive","Because idols have real power over food","Because Moses commanded abstinence"], a:0, why:"Verses 12-13 say wounding their weak conscience is sinning against Christ, so if meat make my brother to offend, I will eat no flesh while the world standeth." },
      { q:"What limits the liberty of those with knowledge?", choices:["Public opinion polls","Take heed lest this liberty of yours become a stumblingblock to them that are weak","Church penalties for eating meat","Nothing limits liberty"], a:1, why:"Verse 9 says but take heed lest by any means this liberty of yours become a stumblingblock to them that are weak." }
    ] },
  { n:9, summary:"Paul answers those who examine him: he is an apostle, free, having seen Jesus Christ our Lord, and the Corinthians themselves are the seal of his apostleship. Like a soldier, a vineyard planter, and a shepherd living from his work, he had power to be supported; the Lord ordained that they which preach the gospel should live of the gospel. Yet he used none of these things, lest he should hinder the gospel: necessity is laid upon me, and woe is unto me if I preach not the gospel — his reward is to preach without charge. Free from all men, he made himself servant unto all: to the Jews as a Jew, to the weak as weak — all things to all men, that he might by all means save some. Then the athlete's image: every man that striveth for the mastery is temperate in all things, so Paul keeps under his body, lest, having preached to others, he himself should be a castaway.",
    context:"Paul defends his rights as an apostle, then explains that he waived them to remove every obstacle from the gospel, disciplining himself like a runner.",
    keyVerses:[
      { ref:"1 Corinthians 9:16", text:"For though I preach the gospel, I have nothing to glory of: for necessity is laid upon me; yea, woe is unto me, if I preach not the gospel!" },
      { ref:"1 Corinthians 9:22", text:"To the weak became I as weak, that I might gain the weak: I am made all things to all men, that I might by all means save some." },
      { ref:"1 Corinthians 9:24", text:"Know ye not that they which run in a race run all, but one receiveth the prize? So run, that ye may obtain." }
    ],
    takeaway:"Serve willingly, adapt to reach people for the gospel's sake, and discipline yourself to obtain the incorruptible crown.",
    quiz:[
      { q:"What image from the law of Moses does Paul cite for a preacher's right to support?", choices:["Thou shalt not muzzle the mouth of the ox that treadeth out the corn","The sabbath rest of the land","The year of jubilee","The tithe of the herds"], a:0, why:"Verse 9 quotes the law of Moses: Thou shalt not muzzle the mouth of the ox that treadeth out the corn." },
      { q:"Why did Paul decline the support he had a right to?", choices:["Tentmaking paid him better","He suffered all things, lest he should hinder the gospel of Christ","The Corinthians refused to give","Other apostles forbade him"], a:1, why:"Verse 12 says nevertheless we have not used this power; but suffer all things, lest we should hinder the gospel of Christ." },
      { q:"What does the race image teach about self-discipline?", choices:["Only one soul can be saved","Discipline belongs to athletes alone","Every man that striveth for the mastery is temperate in all things, so run to obtain the incorruptible crown","Grace makes effort unnecessary"], a:2, why:"Verses 24-25 say they which run in a race run all, but one receiveth the prize, and every man that striveth for the mastery is temperate in all things." }
    ] },
  { n:10, summary:"Paul recalls that Israel's fathers were baptized unto Moses in the cloud and in the sea and drank of that spiritual Rock — and that Rock was Christ. Yet with many of them God was not well pleased: these things were our examples, written for our admonition. So flee idolatry: do not be idolaters as they were, or commit fornication as twenty and three thousand fell in one day; let him that thinketh he standeth take heed lest he fall. God is faithful: with every common temptation He will make a way to escape, that ye may be able to bear it. The argument turns to the sacrament: the cup is the communion of the blood of Christ, the bread the communion of His body — we being many are one bread — so ye cannot be partakers of the Lord's table and the table of devils. Meat sold in the shambles may be eaten without question; but whatsoever ye do — eating or drinking — do all to the glory of God.",
    context:"Paul uses Israel's wilderness failures as warnings against idolatry and sin, then binds the sacrament's communion to a clean break with idol feasts.",
    keyVerses:[
      { ref:"1 Corinthians 10:13", text:"There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it." },
      { ref:"1 Corinthians 10:16", text:"The cup of blessing which we bless, is it not the communion of the blood of Christ? The bread which we break, is it not the communion of the body of Christ?" },
      { ref:"1 Corinthians 10:31", text:"Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God." }
    ],
    takeaway:"Whatever you do — even eating and drinking — do all to the glory of God, and flee from idolatry.",
    quiz:[
      { q:"Who does Paul say the spiritual Rock that followed Israel in the wilderness was?", choices:["Moses","Christ","Joshua","Aaron"], a:1, why:"Verse 4 says they drank of that spiritual Rock that followed them: and that Rock was Christ." },
      { q:"Why does Paul link the sacrament to the danger of idol feasts?", choices:["Both used temple bread","Feasts were Corinth's only social life","They are the communion of Christ's body and blood, so His table and the table of devils cannot mix","Idol meat was physically harmful"], a:2, why:"Verse 16 calls the cup the communion of the blood of Christ and the bread the communion of the body, and verse 21 forbids partaking of the Lord's table and the table of devils." },
      { q:"What promise does Paul give to those facing temptation?", choices:["God removes every temptation from the faithful","Temptation shows a person is cursed","Only apostles withstand temptation","God is faithful, and will with the temptation make a way to escape, that ye may be able to bear it"], a:3, why:"Verse 13 says God is faithful, who will not suffer you to be tempted above that ye are able, but will with the temptation also make a way to escape." }
    ] },
  { n:11, summary:"After praising the Corinthians for keeping the ordinances, Paul gives two corrections. First, head coverings in prayer: the head of every man is Christ, and the head of the woman is the man; a man praying covered dishonoureth his head, and a woman uncovered dishonoureth hers — yet in the Lord neither is without the other. Second, their gatherings do more harm than good: when they come together it is not to eat the Lord's supper — one taketh his own supper before another, leaving one hungry and another drunken. Then the tradition Paul received of the Lord: the same night he was betrayed, Jesus took bread and the cup — my body, which is broken for you; this cup is the new testament in my blood — in remembrance of him. As often as ye eat this bread and drink this cup, ye do shew the Lord's death till he come; whoever eats unworthily, not discerning the Lord's body, eateth damnation to himself — so let a man examine himself.",
    context:"Paul corrects abuses in worship at Corinth — head coverings and the Lord's supper, which the wealthy turned into a class-divided meal — and restates the sacrament's institution.",
    keyVerses:[
      { ref:"1 Corinthians 11:23", text:"For I have received of the Lord that which also I delivered unto you, That the Lord Jesus the same night in which he was betrayed took bread:" },
      { ref:"1 Corinthians 11:26", text:"For as often as ye eat this bread, and drink this cup, ye do shew the Lord's death till he come." },
      { ref:"1 Corinthians 11:28", text:"But let a man examine himself, and so let him eat of that bread, and drink of that cup." }
    ],
    takeaway:"Partake of the sacrament remembering Christ's body and blood, examining yourself and showing His death until He comes.",
    quiz:[
      { q:"On what night did Paul say the Lord Jesus took bread?", choices:["The night of the triumphal entry","The night of the transfiguration","The same night in which he was betrayed","The night of the last discourse only"], a:2, why:"Verse 23 says the Lord Jesus the same night in which he was betrayed took bread." },
      { q:"What was wrong with the Corinthians' observance of the Lord's supper?", choices:["They met on the wrong day","They lacked enough vessels","No one was allowed to speak","Every one took his own supper before others, leaving one hungry and another drunken"], a:3, why:"Verse 21 says in eating every one taketh before other his own supper: and one is hungry, and another is drunken." },
      { q:"How should a person prepare to partake of the bread and cup?", choices:["Let a man examine himself, and so eat of that bread, and drink of that cup","Fast for three days first","Request a leader's permission","Partake only when feeling worthy by nature"], a:0, why:"Verse 28 says but let a man examine himself, and so let him eat of that bread, and drink of that cup." }
    ] },
  { n:12, summary:"Paul would not have them ignorant about spiritual gifts: no man can say that Jesus is the Lord, but by the Holy Ghost. There are diversities of gifts, but the same Spirit — word of wisdom, word of knowledge, faith, healing, miracles, prophecy, discerning of spirits, tongues, interpretation — and the manifestation of the Spirit is given to every man to profit withal. All these work that one and the selfsame Spirit, dividing to every man severally as he will; by one Spirit we are all baptized into one body, whether Jews or Gentiles, bond or free. Then the body image: the foot cannot say, Because I am not the hand, I am not of the body; God set the members as it pleased Him, honoring the part that lacked, so there is no schism — if one member suffers, all suffer with it. Now ye are the body of Christ, and members in particular; covet earnestly the best gifts — and yet shew I unto you a more excellent way.",
    context:"Paul teaches that the same Spirit gives diverse spiritual gifts to every member for the good of all, making the church one body in Christ.",
    keyVerses:[
      { ref:"1 Corinthians 12:7", text:"But the manifestation of the Spirit is given to every man to profit withal." },
      { ref:"1 Corinthians 12:12", text:"For as the body is one, and hath many members, and all the members of that one body, being many, are one body: so also is Christ." },
      { ref:"1 Corinthians 12:27", text:"Now ye are the body of Christ, and members in particular." }
    ],
    takeaway:"The same Spirit gives different gifts to every member so the body of Christ has no schism and cares for all.",
    quiz:[
      { q:"Who decides which gift each member receives, according to this chapter?", choices:["The member's ambition","The congregation's vote","The most gifted leaders","The selfsame Spirit, dividing to every man severally as he will"], a:3, why:"Verse 11 says all these worketh that one and the selfsame Spirit, dividing to every man severally as he will." },
      { q:"Why does Paul compare the church to a body with many members?", choices:["To show that different members need one another, with no schism in the body","Because Greeks admired anatomy","To rank the gifts from best to worst","To explain the senses"], a:0, why:"Verses 21-25 show the eye cannot say to the hand, I have no need of thee, so that there should be no schism in the body." },
      { q:"What does this chapter say to a member who feels unimportant?", choices:["Only visible gifts matter","Those members which seem more feeble are necessary, and God gives more honor to the part that lacked","Every member must have the same gift","Lesser members should step aside"], a:1, why:"Verses 22-24 say those members of the body, which seem to be more feeble, are necessary, and God gives more abundant honor to that part which lacked." }
    ] },
  { n:13, summary:"Paul places love at the center of the gift debate: though I speak with the tongues of men and of angels, and have not charity, I am become as sounding brass, or a tinkling cymbal. Prophecy, all mysteries and knowledge, faith to remove mountains, giving all goods to feed the poor, even a body to be burned — without charity it profiteth nothing. Then the character of charity: it suffereth long, and is kind; envieth not, vaunteth not itself, is not puffed up; doth not behave itself unseemly, seeketh not her own, is not easily provoked, thinketh no evil; rejoiceth not in iniquity, but rejoiceth in the truth; and beareth, believeth, hopeth, and endureth all things. Charity never faileth, while prophecies, tongues, and partial knowledge shall be done away when that which is perfect is come; now we see through a glass, darkly, but then face to face. And now abideth faith, hope, charity, these three; but the greatest of these is charity.",
    context:"Paul interrupts his teaching on spiritual gifts with a hymn to charity, showing that without love even prophecy, knowledge, faith, and sacrifice are nothing.",
    keyVerses:[
      { ref:"1 Corinthians 13:4", text:"Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up," },
      { ref:"1 Corinthians 13:12", text:"For now we see through a glass, darkly; but then face to face: now I know in part; but then shall I know even as also I am known." },
      { ref:"1 Corinthians 13:13", text:"And now abideth faith, hope, charity, these three; but the greatest of these is charity." }
    ],
    takeaway:"Spiritual gifts without charity profit nothing; the greatest gift is charity, which never fails.",
    quiz:[
      { q:"What is a person without charity like, even if he speaks with the tongues of men and of angels?", choices:["Sounding brass, or a tinkling cymbal","A trumpet giving an uncertain sound","A river without water","A lamp under a bushel"], a:0, why:"Verse 1 says though I speak with the tongues of men and of angels, and have not charity, I am become as sounding brass, or a tinkling cymbal." },
      { q:"Why will prophecies, tongues, and knowledge fail or cease?", choices:["They were never true gifts","We know and prophesy only in part, and the perfect will do away the partial","The Corinthians abused them","They belong only to childhood"], a:1, why:"Verses 9-10 say for we know in part, and we prophesy in part. But when that which is perfect is come, then that which is in part shall be done away." },
      { q:"Which of the three abiding virtues is greatest, and why?", choices:["Faith, for it moves mountains","Hope, for it endures trials","Charity, the greatest of the three, which never fails","Knowledge, for it solves mysteries"], a:2, why:"Verse 13 says and now abideth faith, hope, charity, these three; but the greatest of these is charity, for charity never faileth." }
    ] },
  { n:14, summary:"Pursue charity, and desire spiritual gifts — but rather that ye may prophesy, for prophecy edifies the church, while an unknown tongue edifies only the speaker. Illustrations follow: an uncertain trumpet cannot prepare anyone for battle, and without meaning a voice makes us barbarians to one another — so pray and sing with the spirit and with the understanding also. Paul thanks God he speaks with tongues more than they all, yet in the church he would rather speak five words with his understanding to teach others also than ten thousand words in an unknown tongue. Tongues are a sign to unbelievers, but prophecy convinces them, making the secrets of the heart manifest so they worship God. Order governs worship: tongues by two or at the most three, by course, with an interpreter — else silence; prophets speak two or three while others judge; for God is not the author of confusion, but of peace. Let all things be done decently and in order.",
    context:"Paul ranks prophecy above tongues in public worship, sets rules of order for gifts and speakers, and urges that all things be done decently and in order.",
    keyVerses:[
      { ref:"1 Corinthians 14:19", text:"Yet in the church I had rather speak five words with my understanding, that by my voice I might teach others also, than ten thousand words in an unknown tongue." },
      { ref:"1 Corinthians 14:33", text:"For God is not the author of confusion, but of peace, as in all churches of the saints." },
      { ref:"1 Corinthians 14:40", text:"Let all things be done decently and in order." }
    ],
    takeaway:"In worship, seek to edify: speak to be understood, for God is not the author of confusion but of peace.",
    quiz:[
      { q:"How many words does Paul prefer to speak with understanding in the church over ten thousand in an unknown tongue?", choices:["Three","Five","Ten","Twenty"], a:1, why:"Verse 19 says yet in the church I had rather speak five words with my understanding, that by my voice I might teach others also." },
      { q:"Why does Paul rank prophecy above tongues in public worship?", choices:["Prophecy is older than tongues","Tongues were banned in Corinth","Prophecy edifies the whole church, while tongues edify only the speaker unless interpreted","Prophecy requires no study"], a:2, why:"Verses 3-5 say prophecy speaks to edification and exhortation and comfort, while he that speaketh in an unknown tongue edifieth himself." },
      { q:"What rule does Paul give for all things done in worship?", choices:["The loudest voice leads","Spontaneity outranks preparation","Gifts exist for display","Let all things be done decently and in order"], a:3, why:"Verse 40 says let all things be done decently and in order, and verse 26 says let all things be done unto edifying." }
    ] },
  { n:15, summary:"Paul first delivers the gospel he received: Christ died for our sins, was buried, and rose again the third day, appearing to Cephas, the twelve, above five hundred brethren at once, and last of all to Paul. Then the logic: if the dead rise not, Christ is not risen, preaching and faith are vain, ye are yet in your sins, and they which are fallen asleep in Christ are perished. But now is Christ risen, the firstfruits of them that slept: as in Adam all die, even so in Christ shall all be made alive, until the last enemy, death, is destroyed. What body will the dead be raised with? Sown in corruption, raised in incorruption; sown a natural body, raised a spiritual body — as we bore the image of the earthy, we shall bear the image of the heavenly. At the last trump the dead shall be raised incorruptible and we shall all be changed — death is swallowed up in victory — so abound in the work of the Lord.",
    context:"Paul confronts some in Corinth who denied the resurrection, anchoring the whole gospel in Christ's rising and explaining how the dead will be raised.",
    keyVerses:[
      { ref:"1 Corinthians 15:20", text:"But now is Christ risen from the dead, and become the firstfruits of them that slept." },
      { ref:"1 Corinthians 15:22", text:"For as in Adam all die, even so in Christ shall all be made alive." },
      { ref:"1 Corinthians 15:58", text:"Therefore, my beloved brethren, be ye steadfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord." }
    ],
    takeaway:"Because Christ is risen, all will be raised and changed to immortality — so abound in the work of the Lord.",
    quiz:[
      { q:"About how many brethren saw the risen Christ at once, according to Paul?", choices:["One hundred and twenty","Three hundred","Above five hundred","A thousand"], a:2, why:"Verse 6 says he was seen of above five hundred brethren at once; of whom the greater part remain unto this present." },
      { q:"How does Paul answer the question of what body the dead will be raised with?", choices:["The exact same body unchanged","No body at all, spirit only","A dim copy of the old body","Sown a natural body, raised a spiritual body in incorruption and glory"], a:3, why:"Verses 42-44 say it is sown in corruption and raised in incorruption, sown a natural body, raised a spiritual body." },
      { q:"What does the resurrection mean for daily labor in the Lord?", choices:["Be steadfast, unmoveable, always abounding in the work of the Lord, for labour in Him is not in vain","Work is pointless because death wins","Only preaching counts as labor","Effort matters only in this life"], a:0, why:"Verse 58 says therefore... be ye steadfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord." }
    ] },
  { n:16, summary:"Paul's last chapter is practical: concerning the collection for the saints, every one is to lay by him in store on the first day of the week, as God hath prospered him, so approved messengers can carry the gift to Jerusalem. His travel plans run through Macedonia to Corinth — perhaps to winter with them — while he tarries at Ephesus until Pentecost, for a great door and effectual is opened unto me, and there are many adversaries. If Timotheus comes, see that he may be with you without fear, for he worketh the work of the Lord; and the household of Stephanas, who addicted themselves to the ministry of the saints, deserve the saints' submission and acknowledgment. The exhortations come in short strokes: Watch ye, stand fast in the faith, quit you like men, be strong; let all your things be done with charity; Aquila and Priscilla salute them much in the Lord. Paul adds his salutation with his own hand: my love be with you all in Christ Jesus. Amen.",
    context:"Paul closes with practical instructions: a weekly collection for the poor saints at Jerusalem, travel plans from Ephesus, exhortations to watchfulness, and greetings.",
    keyVerses:[
      { ref:"1 Corinthians 16:2", text:"Upon the first day of the week let every one of you lay by him in store, as God hath prospered him, that there be no gatherings when I come." },
      { ref:"1 Corinthians 16:13", text:"Watch ye, stand fast in the faith, quit you like men, be strong." },
      { ref:"1 Corinthians 16:14", text:"Let all your things be done with charity." }
    ],
    takeaway:"Watch, stand fast in the faith, be strong — and let all your things be done with charity.",
    quiz:[
      { q:"Until which feast did Paul say he would tarry at Ephesus?", choices:["Passover","Tabernacles","Pentecost","Dedication"], a:3, why:"Verse 8 says but I will tarry at Ephesus until Pentecost." },
      { q:"How did Paul direct the Corinthians to gather money for the poor saints at Jerusalem?", choices:["Lay by him in store on the first day of the week, as God hath prospered him","Levy a tax on every household","Sell the meetinghouse","Wait for one large gift at his arrival"], a:0, why:"Verses 1-2 say upon the first day of the week let every one of you lay by him in store, as God hath prospered him, that there be no gatherings when I come." },
      { q:"How did Paul ask the Corinthians to treat Timotheus when he came?", choices:["Test him strictly before trusting him","See that he may be with you without fear, and let no man despise him","Keep him at a distance","Send him on to Macedonia quickly"], a:1, why:"Verses 10-11 say see that he may be with you without fear: for he worketh the work of the Lord... let no man therefore despise him." }
    ] }
);
